    private static final Logger NOTIFY = LoggerFactory.getLogger("NOTIFY");

    /** Source of the monotonically increasing {@code seq} carried by each {@link OwnerCreatedAuditEvent}. */
    private static final AtomicLong AUDIT_SEQ = new AtomicLong();

    private final ClinicService clinicService;

    private final OwnerMapper ownerMapper;

    private final PetMapper petMapper;

    private final VisitMapper visitMapper;

    private final IdempotencyStore idempotencyStore;

    private final HttpServletRequest request;

    private final ObjectMapper objectMapper;

    public OwnerRestControllerV1(ClinicService clinicService,
                                 OwnerMapper ownerMapper,
                                 PetMapper petMapper,
                                 VisitMapper visitMapper,
                                 IdempotencyStore idempotencyStore,
                                 HttpServletRequest request,
                                 ObjectMapper objectMapper) {
        this.clinicService = clinicService;
        this.ownerMapper = ownerMapper;
        this.petMapper = petMapper;
        this.visitMapper = visitMapper;
        this.idempotencyStore = idempotencyStore;
        this.request = request;
        this.objectMapper = objectMapper;
    }

    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
    @Override
    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
        Collection<Owner> owners;
        if (lastName != null) {
            owners = this.clinicService.findOwnerByLastName(lastName);
        } else {
            owners = this.clinicService.findAllOwners();
        }
        if (owners.isEmpty()) {
            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
        }
        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
    }

    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
    @Override
    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
        Owner owner = this.clinicService.findOwnerById(ownerId);
        if (owner == null) {
            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
        }
        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
    }

    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
    @Override
    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
        String idempotencyKey = request.getHeader("Idempotency-Key");
        ResponseEntity<OwnerDto> replayed = replayIdempotent(idempotencyKey);
        if (replayed != null) {
            return replayed;
        }
        HttpHeaders headers = new HttpHeaders();
        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
        String telephone = TelephoneNormalizer.normalize(owner.getTelephone());
        owner.setTelephone(telephone);
        String email = EmailNormalizer.normalize(owner.getEmail());
        owner.setEmail(email);
        normalizeAddress(owner);
        PostcodeValidator.validate(owner.getPostcode(), owner.getCity());
        RegistrationDateValidator.validate(owner.getRegistrationDate());
        LocalDate effectiveRegistrationDate =
            owner.getRegistrationDate() != null ? owner.getRegistrationDate() : LocalDate.now();
        owner.setRegistrationDate(RegistrationDateNormalizer.normalize(effectiveRegistrationDate));
        this.clinicService.createOwner(owner);
        Integer membershipLevel = ownerMapper.membershipLevel(owner);
        AUDIT.info("owner created: id={} memberId={} registrationDate={} membershipLevel={}",
            owner.getId(), owner.getMemberId(), owner.getRegistrationDate(), membershipLevel);
        OwnerCreatedAuditEvent event = new OwnerCreatedAuditEvent(AUDIT_SEQ.incrementAndGet(),
            owner.getId(), owner.getMemberId(), membershipLevel);
        AUDIT.info(objectMapper.writeValueAsString(event));
        idempotencyStore.remember(idempotencyKey, owner.getId());
        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
        headers.setLocation(UriComponentsBuilder.newInstance()
            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
    }

    /**
     * When {@code idempotencyKey} names a create that already succeeded, return the originally
     * created owner with {@code 200 OK} so the repeat is not persisted as a duplicate. Returns
     * {@code null} when there is no key or none has been seen, so the caller proceeds with a
     * normal create.
     */
    private ResponseEntity<OwnerDto> replayIdempotent(String idempotencyKey) {
        return idempotencyStore.find(idempotencyKey)
            .map(this.clinicService::findOwnerById)
            .map(owner -> new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK))
            .orElse(null);
    }

    /**
     * Normalizes the owner's address, preferring the structured form. When a non-blank
     * {@code addressLine1} is supplied, both structured lines are normalized and the flat
     * {@code address} is composed from them: the normalized {@code addressLine1}, and — when
     * {@code addressLine2} is present — a single space followed by the normalized
     * {@code addressLine2}. Otherwise the flat {@code address} is normalized on its own,
     * preserving backward compatibility. Either way a blank address is rejected with a
     * {@code 400 Bad Request} by {@link AddressNormalizer#normalize(String)}.
     */
    private void normalizeAddress(Owner owner) {
        String addressLine1 = owner.getAddressLine1();
        if (addressLine1 != null && !addressLine1.isBlank()) {
            String line1 = AddressNormalizer.normalize(addressLine1);
            owner.setAddressLine1(line1);
            String addressLine2 = owner.getAddressLine2();
            if (addressLine2 != null && !addressLine2.isBlank()) {
                String line2 = AddressNormalizer.normalize(addressLine2);
                owner.setAddressLine2(line2);
                owner.setAddress(line1 + " " + line2);
            } else {
                owner.setAddressLine2(null);
                owner.setAddress(line1);
            }
        } else {
            owner.setAddress(AddressNormalizer.normalize(owner.getAddress()));
        }
    }

    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
    @Override
    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
        if (currentOwner == null) {
            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
        }
        currentOwner.setAddress(ownerFieldsDto.getAddress());
        currentOwner.setCity(ownerFieldsDto.getCity());
        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
        currentOwner.setLastName(ownerFieldsDto.getLastName());
        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
        currentOwner.setEmail(EmailNormalizer.normalize(ownerFieldsDto.getEmail()));
        this.clinicService.saveOwner(currentOwner);
        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
    }

    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
    @Transactional
    @Override
    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
        Owner owner = this.clinicService.findOwnerById(ownerId);
        if (owner == null) {
            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
        }
        this.clinicService.deleteOwner(owner);
        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
    }

    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
    @Override
    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
        Owner owner = this.clinicService.findOwnerById(ownerId);
        if (owner == null) {
            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
        }
        HttpHeaders headers = new HttpHeaders();
        Pet pet = petMapper.toPet(petFieldsDto);
        owner.setId(ownerId);
        pet.setOwner(owner);
        pet.getType().setName(null);
        this.clinicService.savePet(pet);
        PetDto petDto = petMapper.toPetDto(pet);
        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
            .buildAndExpand(pet.getId()).toUri());
        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
    }

    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
    @Override
    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
        if (currentOwner != null) {
            Pet currentPet = this.clinicService.findPetById(petId);
            if (currentPet != null) {
                currentPet.setBirthDate(petFieldsDto.getBirthDate());
                currentPet.setName(petFieldsDto.getName());
                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
                this.clinicService.savePet(currentPet);
                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
            }
        }
        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
    }

    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
    @Override
    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
        HttpHeaders headers = new HttpHeaders();
        Visit visit = visitMapper.toVisit(visitFieldsDto);
        Pet pet = new Pet();
        pet.setId(petId);
        visit.setPet(pet);
        this.clinicService.saveVisit(visit);
        VisitDto visitDto = visitMapper.toVisitDto(visit);
        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
            .buildAndExpand(visit.getId()).toUri());
        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
    }


    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
    @Override
    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
        Owner owner = this.clinicService.findOwnerById(ownerId);
        if (owner != null) {
            Pet pet = owner.getPet(petId);
            if (pet != null) {
                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
            }
        }
        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
    }
}
